assert len(R) == 107, len(R)
for r in R:
    assert len(r) == 8, r

def q(s):
    return "'" + s.replace("'", "''") + "'"

rows = []
for i, (cat, emo, kt, kq, et, eq, zt, zq) in enumerate(R):
    rows.append("(" + ",".join([str(51 + i), q(kt), q(cat), q(emo), q(kq), q(et), q(eq), q(zt), q(zq)]) + ")")

sys.stdout.write(
    "insert into public.bucket_presets (id, title, category, emoji, question, title_en, question_en, title_zh, question_zh) values\n"
    + ",\n".join(rows)
    + "\non conflict (id) do nothing;\n"
)
